const p = $input.first()?.json ?? {};
const required = ['tenant_id','business_id','worker_instance_id','correlation_id','idempotency_key','calendario_id','nome_cliente','telefone','servico','data','hora_inicio','duracao_minutos','start_time','end_time'];
const missing = required.filter((key) => p[key] === undefined || p[key] === null || String(p[key]).trim() === '');
if (missing.length) throw new Error('Contexto de marcacao incompleto: ' + missing.join(', '));
return [{ json: { ...p, work_item_type: 'appointment.create_and_verify', work_item_status: 'created', priority: 'normal' } }];

const p = $('Validar Contexto Marcacao').item.json;
const w = $input.first().json;
return [{ json: { ...p, work_item_id: w.work_item_id, work_item_status: w.status } }];

const p = $('Preparar Operacao Agenda').item.json;
const r = $input.first().json;
if (r.status !== 'ok' || !r.google_event_id) throw new Error('Criacao da marcacao nao confirmada pelo Tool Agenda');
return [{ json: { tenant_id: p.tenant_id, business_id: p.business_id, worker_instance_id: p.worker_instance_id, correlation_id: p.correlation_id, calendar_id: p.calendario_id, google_event_id: r.google_event_id, customer_id: p.telefone, start_time: p.start_time, end_time: p.end_time, work_item_id: p.work_item_id, appointment_result: r } }];

const row = $input.first()?.json ?? {};
const result = row.result ?? {};
const eventId = result.google_event_id ?? result.appointment_result?.google_event_id ?? null;
const original = $('Validar Contexto Marcacao').item.json;
const reuse = row.status === 'verified' && Boolean(eventId);
return [{ json: { ...original, work_item_id: row.work_item_id, work_item_status: row.status, existing_result: result, existing_google_event_id: eventId, idempotency_reuse: reuse } }];
